{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much can I get for my car in Brisbane?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The offer depends on the make, model, year, condition, kilometres, registration status, location and how easy the car is to access for towing. Parts and recycling demand also play a part. Send us the details and photos and we'll give you a clear quote, up to $9,999 for the right vehicle, before you book anything in."
      }
    },
    {
      "@type": "Question",
      "name": "Is towing free when Aplus Car Removal buys my car?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Free towing is usually included when Aplus buys your vehicle, as long as the location and access are suitable for our tow trucks. Tighter spots may need a quick chat first so we can plan the pickup properly."
      }
    },
    {
      "@type": "Question",
      "name": "How quickly can my car be picked up?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Same-day or next-day pickup may be available, depending on booking time, your suburb, traffic and how accessible the vehicle is. We'll give you a realistic pickup window when you book."
      }
    },
    {
      "@type": "Question",
      "name": "Do you buy damaged cars?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We consider accident-damaged, hail-damaged, mechanically damaged and non-running vehicles. A damaged car can still have real value in parts and materials."
      }
    },
    {
      "@type": "Question",
      "name": "Do you buy unregistered cars?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, unregistered cars can usually be assessed for a quote. It helps to have proof of ownership on hand, and the vehicle should be accessible for pickup."
      }
    },
    {
      "@type": "Question",
      "name": "Do I need a roadworthy certificate?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For car removal or selling to a vehicle buyer, a roadworthy certificate is often not required, especially for damaged, scrap or unwanted cars. Private sale or registration transfer rules can be different."
      }
    },
    {
      "@type": "Question",
      "name": "What paperwork do I need to sell my car in QLD?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You'll generally need proof of ownership, photo ID, your registration details if the car is still registered, and the keys if you have them. Let us know upfront if there is finance owing."
      }
    },
    {
      "@type": "Question",
      "name": "Can I sell a car that does not start?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We regularly buy non-running cars, including vehicles with flat batteries, engine trouble, gearbox faults, overheating issues or a seized engine. Towing access still matters here."
      }
    },
    {
      "@type": "Question",
      "name": "Do you buy scrap or junk cars?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Old, incomplete, wrecked, rusted or end-of-life cars can still hold value through their parts and recyclable materials."
      }
    },
    {
      "@type": "Question",
      "name": "How do you work out the value of a scrap car?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We look at the car's condition, weight and materials, demand for its parts, and factors like the catalytic converter where relevant. Location and access for towing also come into it."
      }
    },
    {
      "@type": "Question",
      "name": "Do you buy trucks, utes, vans and 4WDs?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, we buy a range of vehicles beyond standard passenger cars, including light trucks, utes, vans, SUVs and 4WDs."
      }
    },
    {
      "@type": "Question",
      "name": "Can you remove cars from unit complexes, yards or tight access areas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "In most cases, yes, as long as access is suitable for our tow truck. Send us a few photos of the driveway, gate or parking area so we can plan the pickup."
      }
    },
    {
      "@type": "Question",
      "name": "What details should I send for a quick quote?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Send us the make, model, year, suburb, condition, whether it starts and drives, registration status, a few photos, whether you have the keys, and any notes on tow access."
      }
    },
    {
      "@type": "Question",
      "name": "What happens to my car after it's removed?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Once your car is picked up, reusable parts may be recovered for resale and recyclable materials are processed responsibly."
      }
    },
    {
      "@type": "Question",
      "name": "Can I sell a car with finance owing?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Cars with finance owing need a bit more care. Check your current payout figure with your finance provider before selling, and let us know upfront if there's money owing."
      }
    },
    {
      "@type": "Question",
      "name": "Do you service all Brisbane suburbs?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We cover Brisbane's northside, southside, east and west, along with surrounding areas. Coverage can vary a little depending on the day and tow access."
      }
    },
    {
      "@type": "Question",
      "name": "Do you remove cars from Logan, Ipswich, Gold Coast or Sunshine Coast?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, service in these areas depends on location, booking time and tow access on the day."
      }
    },
    {
      "@type": "Question",
      "name": "Why should I use Aplus instead of selling privately?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Selling privately can take time, especially if the car is old, damaged, unregistered or not running. Aplus offers a simpler option if you'd rather get a quote and have the vehicle picked up."
      }
    }
  ]
}

